const fs = require('fs');
const path = require('path');
const os = require('os');

const configPath = path.join(os.homedir(), 'AppData', 'Roaming', 'Claude', 'claude_desktop_config.json');
const mcpPath = path.resolve(__dirname, 'nova-memory-mcp.mjs').replace(/\\/g, '/');

let config = JSON.parse(fs.readFileSync(configPath, 'utf8'));

config.mcpServers['nova-memory'] = {
  command: 'node',
  args: [mcpPath],
  env: { NOVA_MCP_MODE: 'true' }
};

fs.writeFileSync(configPath, JSON.stringify(config, null, 2));
console.log('✅ Nova Memory updated in Claude Desktop');
console.log('📁 MCP Path:', mcpPath);
console.log('🎉 Please restart Claude Desktop to use the updated Nova Memory!');